#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include "../src/hmb3d.h"

#ifndef HMB3D_TOOL_MAX_FILE_BYTES
#define HMB3D_TOOL_MAX_FILE_BYTES (16UL * 1024UL * 1024UL)
#endif

static unsigned char g_file[HMB3D_TOOL_MAX_FILE_BYTES];
static hmb3d_model g_model;
static hmb3d_diag g_diag;

static void print_fixed(FILE *f, hmb3d_fixed v)
{
    hmb3d_u32 whole;
    hmb3d_u32 frac;
    hmb3d_u32 dec;
    hmb3d_u32 mag;
    if (v < 0) {
        fputc('-', f);
        if (v == HMB3D_FIXED_MIN) {
            mag = 2147483648UL;
        } else {
            mag = (hmb3d_u32)(-v);
        }
    } else {
        mag = (hmb3d_u32)v;
    }
    whole = mag >> HMB3D_FIXED_SHIFT;
    frac = mag & 65535UL;
    dec = (frac * 1000000UL + 32768UL) >> 16;
    if (dec >= 1000000UL) {
        whole++;
        dec -= 1000000UL;
    }
    fprintf(f, "%lu.%06lu", (unsigned long)whole, (unsigned long)dec);
}

static int read_file(const char *path, hmb3d_u32 *out_size)
{
    FILE *fp;
    long end_pos;
    size_t got;
    fp = fopen(path, "rb");
    if (fp == 0) {
        fprintf(stderr, "hmb2obj: cannot open input: %s\n", path);
        return 0;
    }
    if (fseek(fp, 0L, SEEK_END) != 0) {
        fclose(fp);
        return 0;
    }
    end_pos = ftell(fp);
    if (end_pos < 0L || (unsigned long)end_pos > HMB3D_TOOL_MAX_FILE_BYTES) {
        fprintf(stderr, "hmb2obj: input too large for static buffer: %s\n", path);
        fclose(fp);
        return 0;
    }
    if (fseek(fp, 0L, SEEK_SET) != 0) {
        fclose(fp);
        return 0;
    }
    got = fread(g_file, 1U, (size_t)end_pos, fp);
    fclose(fp);
    if (got != (size_t)end_pos) {
        fprintf(stderr, "hmb2obj: short read\n");
        return 0;
    }
    *out_size = (hmb3d_u32)got;
    return 1;
}

static void write_obj(FILE *out, const hmb3d_model *m)
{
    hmb3d_u32 i;
    hmb3d_u32 oi;
    fprintf(out, "# Generated by hmb3d C89 no-heap decoder\n");
    fprintf(out, "# vertices=%lu uvs=%lu faces=%lu objects=%lu\n",
            (unsigned long)m->vertex_count,
            (unsigned long)m->uv_count,
            (unsigned long)m->face_count,
            (unsigned long)m->object_count);
    for (i = 0U; i < m->vertex_count; ++i) {
        fputs("v ", out);
        print_fixed(out, m->vertices[i].x);
        fputc(' ', out);
        print_fixed(out, m->vertices[i].y);
        fputc(' ', out);
        print_fixed(out, m->vertices[i].z);
        fputc('\n', out);
    }
    for (i = 0U; i < m->uv_count; ++i) {
        fputs("vt ", out);
        print_fixed(out, m->uvs[i].u);
        fputc(' ', out);
        print_fixed(out, m->uvs[i].v);
        fputc('\n', out);
    }
    for (oi = 0U; oi < m->object_count; ++oi) {
        const hmb3d_object *obj;
        hmb3d_u32 fi;
        obj = &m->objects[oi];
        fprintf(out, "o %s\n", obj->name);
        for (fi = obj->first_face; fi < obj->first_face + obj->face_count && fi < m->face_count; ++fi) {
            const hmb3d_face *face;
            hmb3d_u32 c;
            face = &m->faces[fi];
            if ((face->flags & HMB3D_FACE_HOLE) != 0U) {
                fprintf(out, "# skipped hole face at %lu\n", (unsigned long)fi);
                continue;
            }
            if (face->corner_count < 2U) {
                continue;
            }
            fputs("f", out);
            for (c = 0U; c < (hmb3d_u32)face->corner_count; ++c) {
                const hmb3d_corner *corner;
                corner = &m->corners[face->first_corner + c];
                if (corner->vertex == HMB3D_INVALID_INDEX) {
                    fputs(" 1", out);
                } else {
                    fprintf(out, " %lu", (unsigned long)(corner->vertex + 1U));
                }
                if (corner->uv != HMB3D_INVALID_INDEX) {
                    fprintf(out, "/%lu", (unsigned long)(corner->uv + 1U));
                }
            }
            fputc('\n', out);
        }
    }
}

static void print_diag(FILE *f, const hmb3d_diag *d)
{
    fprintf(f, "status=%s warnings=0x%08lx chunks=%lu unknown=%lu polh=%lu hmp=%lu bad_indices=%lu saturated=%lu clipped(v/u/f/c)=%lu/%lu/%lu/%lu\n",
            hmb3d_error_string(d->code),
            (unsigned long)d->warning_flags,
            (unsigned long)d->chunks_seen,
            (unsigned long)d->chunks_unknown,
            (unsigned long)d->polh_seen,
            (unsigned long)d->hmp_seen,
            (unsigned long)d->bad_indices,
            (unsigned long)d->values_saturated,
            (unsigned long)d->clipped_vertices,
            (unsigned long)d->clipped_uvs,
            (unsigned long)d->clipped_faces,
            (unsigned long)d->clipped_corners);
}

int main(int argc, char **argv)
{
    hmb3d_u32 size;
    FILE *out;
    int code;
    if (argc < 3) {
        fprintf(stderr, "usage: hmb2obj input.hmb output.obj\n");
        return 2;
    }
    if (!read_file(argv[1], &size)) {
        return 1;
    }
    code = hmb3d_load_memory(g_file, size, &g_model, &g_diag);
    print_diag(stderr, &g_diag);
    if (code != HMB3D_OK) {
        return 1;
    }
    out = fopen(argv[2], "wb");
    if (out == 0) {
        fprintf(stderr, "hmb2obj: cannot open output: %s\n", argv[2]);
        return 1;
    }
    write_obj(out, &g_model);
    fclose(out);
    return 0;
}
